1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit, or publishes several staged batches atomically
5	// with CommitGroup. Readers only ever see committed batches, in strictly
6	// increasing sequence order starting at 1. Reads locate each batch
7	// through a segment-level index that Open rebuilds from the segment
8	// files, so losing the index never loses data.
9	package log
10	
11	import (
12		"errors"
13		"fmt"
14		"os"
15		"path/filepath"
16		"sort"
17		"strconv"
18		"strings"
19		"sync"
20	)
21	
22	var (
23		// ErrNotCommitted is returned when reading a sequence that has been
24		// staged with Append but not yet committed.
25		ErrNotCommitted = errors.New("log: batch not committed")
26		// ErrUnknownBatch is returned for sequence 0, sequences that were
27		// never reserved, sequences beyond the reserved range, and batches
28		// that have already been committed.
29		ErrUnknownBatch = errors.New("log: unknown batch")
30		// ErrCorruptSegment is returned when a segment file fails validation
31		// while opening or scanning the log.
32		ErrCorruptSegment = errors.New("log: corrupt segment")
33		// ErrInvalidOptions is returned by Open when the options are not
34		// usable, e.g. a non-positive segment capacity.
35		ErrInvalidOptions = errors.New("log: invalid options")
36		// ErrSyncFailed is returned by Commit and CommitGroup when
37		// Options.Sync is set and fsyncing the segment file fails. The
38		// batches stay staged and keep their reserved sequences; committing
39		// them again retries.
40		ErrSyncFailed = errors.New("log: sync failed")
41	)
42	
43	var errClosed = errors.New("log: closed")
44	
45	// syncFile fsyncs a segment file. It is a variable so tests can
46	// simulate sync failures.
47	var syncFile = func(f *os.File) error { return f.Sync() }
48	
49	// Options configures a Log opened with Open.
50	type Options struct {
51		// SegmentBytes is the capacity of one segment file in bytes. Once a
52		// non-empty segment would exceed it, the log rolls to a new segment.
53		// A single batch or group larger than the capacity occupies its own
54		// segment. Must be positive.
55		SegmentBytes int
56		// Sync makes Commit and CommitGroup fsync the segment file before
57		// returning, so a returned commit is durable.
58		Sync bool
59	}
60	
61	// Batch is a group of records identified by a single sequence number.
62	// A Batch returned by Append is staged; after Commit or CommitGroup it
63	// is readable.
64	type Batch struct {
65		seq     uint64
66		records [][]byte
67		owner   *Log
68	}
69	
70	// Seq returns the sequence number reserved for the batch.
71	func (b Batch) Seq() uint64 { return b.seq }
72	
73	// Records returns a copy of the batch's records.
74	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
75	
76	// Segment describes one segment file by the committed sequences it holds.
77	type Segment struct {
78		FirstSeq uint64
79		LastSeq  uint64
80	}
81	
82	// entryRef locates one committed batch body inside a segment file. The
83	// index is rebuilt from the segment files every time the log opens, so
84	// its loss or invalidation is always safe. gen is the publication
85	// generation of the commit that published the batch; every member of a
86	// group commit shares one gen, which lets a streaming replay snapshot
87	// see the whole group or none of it.
88	type entryRef struct {
89		seg    int // segment file number
90		off    int // offset of the batch body within the segment
91		length int // length of the batch body
92		gen    uint64
93	}
94	
95	// Log is an append-only batch-commit log stored in a directory of
96	// segment files. It is safe for concurrent use, but the writer side is
97	// expected to be a single goroutine (see README Limits).
98	//
99	// The read and write paths are decoupled: writers take mu exclusively,
100	// while readers hold it only for the brief index and staged-state
101	// lookups. Segment file reads, decoding and user callbacks happen
102	// outside the lock, so a slow reader or a long replay never blocks a
103	// committing writer.
104	type Log struct {
105		dir  string
106		opts Options
107	
108		// mu guards the mutable index and write state below. Readers never
109		// hold it across file I/O, decoding or callbacks.
110		mu         sync.RWMutex
111		file       *os.File // current segment, nil until first write
112		fileSize   int
113		segIndex   int // index of the current segment file, 0 = none yet
114		curBatches int // committed batches in the current segment
115		nextSeq    uint64
116		staged     map[uint64][][]byte
117		index      map[uint64]entryRef
118		segs       []Segment // segments holding at least one committed batch
119		gen        uint64    // publication generation of the last commit
120		closed     bool
121	}
122	
123	// Open opens the log in dir, creating the directory if needed. Existing
124	// segments are validated and their committed batches become readable,
125	// and the segment-level index is rebuilt from them. A half-written tail
126	// of the last segment — the remnant of a crash mid-write — is replaced
127	// by a durable hole marker without error and its reserved sequences stay
128	// permanent holes across reopens; any other inconsistency is
129	// ErrCorruptSegment.
130	func Open(dir string, opts Options) (*Log, error) {
131		if opts.SegmentBytes <= 0 {
132			return nil, ErrInvalidOptions
133		}
134		if err := os.MkdirAll(dir, 0o755); err != nil {
135			return nil, err
136		}
137		entries, err := os.ReadDir(dir)
138		if err != nil {
139			return nil, err
140		}
141		var indices []int
142		for _, e := range entries {
143			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
144				continue
145			}
146			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
147			if err != nil {
148				continue
149			}
150			indices = append(indices, n)
151		}
152		sort.Ints(indices)
153	
154		l := &Log{
155			dir:     dir,
156			opts:    opts,
157			nextSeq: 1,
158			staged:  make(map[uint64][][]byte),
159			index:   make(map[uint64]entryRef),
160		}
161		for i, n := range indices {
162			data, err := os.ReadFile(l.segmentPath(n))
163			if err != nil {
164				return nil, err
165			}
166			batches, holes, tail, err := parseSegment(data)
167			if err != nil {
168				return nil, err
169			}
170			if tail != nil && i != len(indices)-1 {
171				// A half-written tail is a crash remnant only in the
172				// last segment; anywhere else it is tampering.
173				return nil, ErrCorruptSegment
174			}
175			l.curBatches = len(batches)
176			if len(batches) > 0 {
177				seg := Segment{FirstSeq: ^uint64(0)}
178				for _, pb := range batches {
179					l.index[pb.seq] = entryRef{seg: n, off: pb.off, length: pb.length}
180					if pb.seq < seg.FirstSeq {
181						seg.FirstSeq = pb.seq
182					}
183					if pb.seq > seg.LastSeq {
184						seg.LastSeq = pb.seq
185					}
186				}
187				l.segs = append(l.segs, seg)
188				if seg.LastSeq >= l.nextSeq {
189					l.nextSeq = seg.LastSeq + 1
190				}
191			}
192			if tail != nil {
193				// Replace the torn entry with a durable hole marker so
194				// its reserved sequences stay permanent holes: the
195				// crashed batches stay staged forever and their
196				// sequences are never reused, even across reopens.
197				if err := l.rewriteTail(n, tail.off, tail.seqs); err != nil {
198					return nil, err
199				}
200				holes = append(holes, tail.seqs...)
201			}
202			for _, seq := range holes {
203				if seq == 0 {
204					continue
205				}
206				if _, ok := l.index[seq]; !ok {
207					l.staged[seq] = nil
208				}
209				if seq >= l.nextSeq {
210					l.nextSeq = seq + 1
211				}
212			}
213		}
214		if len(indices) > 0 {
215			l.segIndex = indices[len(indices)-1]
216			if err := l.openCurrent(); err != nil {
217				return nil, err
218			}
219		}
220		return l, nil
221	}
222	
223	// Append stages a batch of records and reserves the next sequence number
224	// for it. The batch becomes readable only after Commit or CommitGroup.
225	func (l *Log) Append(records [][]byte) (Batch, error) {
226		l.mu.Lock()
227		defer l.mu.Unlock()
228		if l.closed {
229			return Batch{}, errClosed
230		}
231		recs := copyRecords(records)
232		seq := l.nextSeq
233		l.nextSeq++
234		l.staged[seq] = recs
235		return Batch{seq: seq, records: recs, owner: l}, nil
236	}
237	
238	// Commit makes a staged batch durable and readable, and returns its
239	// reserved sequence number. Committing a batch that is not staged —
240	// including one already committed — returns ErrUnknownBatch. With
241	// Options.Sync a returned commit is durable; if the fsync fails Commit
242	// returns ErrSyncFailed and the batch stays staged, keeping its
243	// reserved sequence for a retry.
244	func (l *Log) Commit(b Batch) (uint64, error) {
245		l.mu.Lock()
246		defer l.mu.Unlock()
247		if l.closed {
248			return 0, errClosed
249		}
250		recs, ok := l.staged[b.seq]
251		if !ok || b.owner != l {
252			return 0, ErrUnknownBatch
253		}
254		entry := encodeBatch(b.seq, recs)
255		off, err := l.writeEntry(entry)
256		if err != nil {
257			return 0, err
258		}
259		if l.opts.Sync {
260			if err := syncFile(l.file); err != nil {
261				// The batch stays staged and keeps its reserved sequence;
262				// a later Commit retries. Drop the un-synced entry so the
263				// retry cannot duplicate it on disk.
264				l.file.Truncate(int64(off))
265				l.fileSize = off
266				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
267			}
268		}
269		delete(l.staged, b.seq)
270		l.gen++
271		l.index[b.seq] = entryRef{seg: l.segIndex, off: off + len(segmentMagic), length: len(entry) - len(segmentMagic) - 4, gen: l.gen}
272		l.commitSpan(b.seq, b.seq, 1)
273		return b.seq, nil
274	}
275	
276	// CommitGroup makes several staged batches durable and readable as one
277	// atomic unit: a single write and, with Options.Sync, a single fsync
278	// covering the whole group. Each batch keeps the sequence it reserved at
279	// Append, and the batches become visible in that reserved order — the
280	// merge never reorders them. If any batch is not staged — including one
281	// already committed — nothing is written and the error is
282	// ErrUnknownBatch. If the fsync fails, the written bytes are rolled back
283	// and every batch stays staged with its reserved sequence; the error is
284	// ErrSyncFailed and retrying the group commits it without duplicating
285	// entries. A crash can never leave half of the group visible: the group
286	// is either wholly durable or wholly staged, and sequences reserved by a
287	// torn group stay permanent holes.
288	func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
289		l.mu.Lock()
290		defer l.mu.Unlock()
291		if l.closed {
292			return nil, errClosed
293		}
294		if len(batches) == 0 {
295			return nil, nil
296		}
297		members := make([]groupMember, len(batches))
298		seqs := make([]uint64, len(batches))
299		seen := make(map[uint64]struct{}, len(batches))
300		for i, b := range batches {
301			recs, ok := l.staged[b.seq]
302			if !ok || b.owner != l {
303				return nil, ErrUnknownBatch
304			}
305			if _, dup := seen[b.seq]; dup {
306				return nil, ErrUnknownBatch
307			}
308			seen[b.seq] = struct{}{}
309			members[i] = groupMember{seq: b.seq, records: recs}
310			seqs[i] = b.seq
311		}
312		entry, offs, lens := encodeGroup(members)
313		base, err := l.writeEntry(entry)
314		if err != nil {
315			return nil, err
316		}
317		if l.opts.Sync {
318			if err := syncFile(l.file); err != nil {
319				// Every batch stays staged and keeps its reserved
320				// sequence; a later CommitGroup retries. Drop the
321				// un-synced group entry so the retry cannot duplicate it.
322				l.file.Truncate(int64(base))
323				l.fileSize = base
324				return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
325			}
326		}
327		first, last := seqs[0], seqs[0]
328		l.gen++
329		for i, m := range members {
330			delete(l.staged, m.seq)
331			l.index[m.seq] = entryRef{seg: l.segIndex, off: base + offs[i], length: lens[i], gen: l.gen}
332			if m.seq < first {
333				first = m.seq
334			}
335			if m.seq > last {
336				last = m.seq
337			}
338		}
339		l.commitSpan(first, last, len(members))
340		return seqs, nil
341	}
342	
343	// Read returns the records of the committed batch with the given
344	// sequence, located directly through the segment-level index. A staged
345	// but uncommitted sequence yields ErrNotCommitted; sequence 0,
346	// never-reserved sequences, and sequences beyond the reserved range
347	// yield ErrUnknownBatch.
348	//
349	// The lock is held only for the index lookup; the segment file is read
350	// and the body decoded without it, so a slow read never blocks writers.
351	func (l *Log) Read(seq uint64) ([][]byte, error) {
352		l.mu.RLock()
353		if l.closed {
354			l.mu.RUnlock()
355			return nil, errClosed
356		}
357		ref, ok := l.index[seq]
358		if !ok {
359			_, staged := l.staged[seq]
360			l.mu.RUnlock()
361			if staged {
362				return nil, ErrNotCommitted
363			}
364			return nil, ErrUnknownBatch
365		}
366		l.mu.RUnlock()
367		return l.readRef(seq, ref)
368	}
369	
370	// scanSnapshot is a read-consistent visibility boundary: a batch is
371	// visible only when its publication generation is <= gen and its
372	// sequence is <= highSeq. The boundary is captured in one brief
373	// read-lock acquisition, so a group that commits after a replay starts
374	// (even one filling an earlier reserved hole) is either wholly inside
375	// the snapshot or wholly outside it.
376	type scanSnapshot struct {
377		gen     uint64
378		highSeq uint64
379	}
380	
381	// Scan replays committed batches with sequence >= from in increasing
382	// sequence order, stopping at the first error returned by fn.
383	//
384	// The replay is a consistent snapshot: batches committed after the
385	// replay starts are invisible to it, and a group commit is seen either
386	// whole or not at all. The replay streams batches straight from the
387	// segment files one sequence at a time and keeps only the current
388	// batch in memory; it never loads the whole replay first. Each
389	// sequence lookup takes the lock briefly, while the file read, decode
390	// and the fn callback all run outside it, so a long replay never
391	// blocks writers.
392	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
393		l.mu.RLock()
394		if l.closed {
395			l.mu.RUnlock()
396			return errClosed
397		}
398		snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
399		l.mu.RUnlock()
400	
401		if from > snap.highSeq {
402			return nil
403		}
404		for seq := from; ; {
405			// One brief read-lock per sequence: only the index metadata is
406			// touched while holding it.
407			l.mu.RLock()
408			ref, ok := l.index[seq]
409			l.mu.RUnlock()
410			// Skip holes (reserved but uncommitted sequences) and batches
411			// published after the snapshot was taken.
412			if ok && ref.gen <= snap.gen {
413				records, err := l.readRef(seq, ref)
414				if err != nil {
415					return err
416				}
417				if err := fn(Batch{seq: seq, records: records, owner: l}); err != nil {
418					return err
419				}
420			}
421			if seq == snap.highSeq {
422				break
423			}
424			seq++
425		}
426		return nil
427	}
428	
429	// Segments lists the segments that hold committed batches, in file
430	// order, each with its first and last committed sequence.
431	func (l *Log) Segments() []Segment {
432		l.mu.RLock()
433		defer l.mu.RUnlock()
434		out := make([]Segment, len(l.segs))
435		copy(out, l.segs)
436		return out
437	}
438	
439	// Close closes the current segment file. The log must not be used
440	// afterwards.
441	func (l *Log) Close() error {
442		l.mu.Lock()
443		defer l.mu.Unlock()
444		if l.closed {
445			return nil
446		}
447		l.closed = true
448		if l.file != nil {
449			return l.file.Close()
450		}
451		return nil
452	}
453	
454	// readRef loads the records of a committed batch straight from its
455	// segment file. It performs no locking and must be called without l.mu
456	// held: the segment read and body decode happen entirely on the read
457	// path, outside the writer lock. The on-disk bytes are immutable once
458	// committed (only the torn tail of the very last segment is ever
459	// rewritten, and that tail never has an index entry), so a ref captured
460	// under the read lock stays valid afterwards. The returned records are
461	// freshly decoded, so callers can mutate them without affecting the
462	// log or later reads.
463	func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, error) {
464		f, err := os.Open(l.segmentPath(ref.seg))
465		if err != nil {
466			return nil, err
467		}
468		defer f.Close()
469		body := make([]byte, ref.length)
470		if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
471			return nil, err
472		}
473		got, records, err := decodeBody(body)
474		if err != nil {
475			return nil, err
476		}
477		if got != seq {
478			return nil, ErrCorruptSegment
479		}
480		return records, nil
481	}
482	
483	// commitSpan records n newly committed batches covering sequences
484	// [first, last] in the segment listing.
485	func (l *Log) commitSpan(first, last uint64, n int) {
486		if l.curBatches == 0 {
487			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
488		} else {
489			seg := &l.segs[len(l.segs)-1]
490			if first < seg.FirstSeq {
491				seg.FirstSeq = first
492			}
493			if last > seg.LastSeq {
494				seg.LastSeq = last
495			}
496		}
497		l.curBatches += n
498	}
499	
500	// rewriteTail drops a torn tail from segment n and, when the torn entry
501	// carried recoverable sequences, replaces it with a synced hole marker
502	// so the reserved sequences stay permanent holes across reopens.
503	func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
504		path := l.segmentPath(n)
505		if err := os.Truncate(path, int64(off)); err != nil {
506			return err
507		}
508		keep := make([]uint64, 0, len(seqs))
509		for _, seq := range seqs {
510			if seq > 0 {
511				keep = append(keep, seq)
512			}
513		}
514		if len(keep) == 0 {
515			return nil
516		}
517		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
518		if err != nil {
519			return err
520		}
521		if _, err := f.Write(encodeHoles(keep)); err != nil {
522			f.Close()
523			return err
524		}
525		if err := f.Sync(); err != nil {
526			f.Close()
527			return err
528		}
529		return f.Close()
530	}
531	
532	// writeEntry appends one encoded entry to the current segment, rolling
533	// to a new segment when the current one is non-empty and would exceed
534	// the configured capacity, and returns the offset the entry was
535	// written at.
536	func (l *Log) writeEntry(entry []byte) (int, error) {
537		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
538			if err := l.file.Close(); err != nil {
539				return 0, err
540			}
541			l.file = nil
542			l.segIndex++
543			l.curBatches = 0
544		}
545		if l.file == nil {
546			if l.segIndex == 0 {
547				l.segIndex = 1
548			}
549			if err := l.openCurrent(); err != nil {
550				return 0, err
551			}
552		}
553		off := l.fileSize
554		n, err := l.file.Write(entry)
555		if err != nil {
556			return 0, err
557		}
558		l.fileSize += n
559		return off, nil
560	}
561	
562	func (l *Log) openCurrent() error {
563		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
564		if err != nil {
565			return err
566		}
567		st, err := f.Stat()
568		if err != nil {
569			f.Close()
570			return err
571		}
572		l.file = f
573		l.fileSize = int(st.Size())
574		return nil
575	}
576	
577	func (l *Log) segmentPath(index int) string {
578		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
579	}
580	
581	func copyRecords(records [][]byte) [][]byte {
582		out := make([][]byte, len(records))
583		for i, r := range records {
584			cp := make([]byte, len(r))
585			copy(cp, r)
586			out[i] = cp
587		}
588		return out
589	}
590

