		switch {
		case bytes.Equal(rest[:4], segmentMagic):
			if len(rest) < entryHeaderLen {
				tail = &segmentTail{off: off, prefixCRC: runCRC}
				if len(rest) >= 12 {
					tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(rest[4:12]))
				}
				return frames, tail, nil
			}
			seq := binary.LittleEndian.Uint64(rest[4:12])
			count := binary.LittleEndian.Uint32(rest[12:16])
			pos, ok := skipRecords(data, off+entryHeaderLen, count)
			if !ok {
				return frames, &segmentTail{off: off, seqs: []uint64{seq}, prefixCRC: runCRC}, nil
			}
			if len(data)-pos < 4 {
				return frames, &segmentTail{off: off, seqs: []uint64{seq}, prefixCRC: runCRC}, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[entryStart:pos]) != crc {
				return nil, nil, ErrCorruptSegment
			}
			off = pos + 4
			runCRC = crc32.Update(runCRC, crc32.IEEETable, data[entryStart:off])
			frames = append(frames, indexFrame{
				kind:   kindData,
				seg:    seg,
				endOff: uint64(off),
				segCRC: runCRC,
				members: []frameMember{{
					seq:    seq,
					off:    uint64(entryStart + len(segmentMagic)),
					length: uint64(pos - entryStart - len(segmentMagic)),
				}},
			})
		case bytes.Equal(rest[:4], groupMagic):
			tail = &segmentTail{off: off, prefixCRC: runCRC}
			if len(rest) < 8 {
				return frames, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			members := make([]frameMember, 0, count)
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 12 {
					// Torn between or inside member headers;
					// recover the member's sequence if whole.
					if len(data)-pos >= 8 {
						tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
					}
					return frames, tail, nil
				}
				mOff := pos
				seq := binary.LittleEndian.Uint64(data[pos : pos+8])
				nrec := binary.LittleEndian.Uint32(data[pos+8 : pos+12])
				tail.seqs = append(tail.seqs, seq)
				npos, ok := skipRecords(data, pos+12, nrec)
				if !ok {
					return frames, tail, nil
				}
				pos = npos
				members = append(members, frameMember{
					seq:    seq,
					off:    uint64(mOff),
					length: uint64(pos - mOff),
				})
			}
			if len(data)-pos < 4 {
				return frames, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[entryStart:pos]) != crc {
				return nil, nil, ErrCorruptSegment
			}
			// Only a complete, checksummed group publishes its
			// members; a torn group above publishes none.
			off = pos + 4
			runCRC = crc32.Update(runCRC, crc32.IEEETable, data[entryStart:off])
			frames = append(frames, indexFrame{
				kind:    kindData,
				seg:     seg,
				endOff:  uint64(off),
				segCRC:  runCRC,
				members: members,
			})
		case bytes.Equal(rest[:4], holeMagic):
			tail := &segmentTail{off: off, prefixCRC: runCRC}
			if len(rest) < 8 {
				return frames, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var seqs []uint64
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 8 {
					tail.seqs = append(tail.seqs, seqs...)
					return frames, tail, nil
				}
				seqs = append(seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
				pos += 8
			}
			if len(data)-pos < 4 {
				tail.seqs = append(tail.seqs, seqs...)
				return frames, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[entryStart:pos]) != crc {
				return nil, nil, ErrCorruptSegment
			}
			off = pos + 4
			runCRC = crc32.Update(runCRC, crc32.IEEETable, data[entryStart:off])
			frames = append(frames, indexFrame{
				kind:   kindHoles,
				seg:    seg,
				endOff: uint64(off),
				segCRC: runCRC,
				seqs:   seqs,
			})
		default:
			return nil, nil, ErrCorruptSegment
		}
	}
	return frames, nil, nil
}

// parseSegment decodes every complete entry in data, returning the
// committed batches (with the offsets of their bodies) and the
// sequences reserved by hole markers. It is used only to classify a
// suffix the index does not cover during an incremental open: a
// truncated tail is reported separately, everything else parses as
// durable-looking entries whose reserved sequences recovery still
// turns into holes, because the index — not structural completeness —
// is what marks a commit.
func parseSegment(data []byte) (batches []parsedBatch, holes []uint64, tail *segmentTail, err error) {
	off := 0
	for off < len(data) {
		rest := data[off:]
		if len(rest) < len(segmentMagic) {
			if !bytes.Equal(rest, segmentMagic[:len(rest)]) {
				return nil, nil, nil, ErrCorruptSegment
			}
			return batches, holes, &segmentTail{off: off}, nil
		}
		switch {
		case bytes.Equal(rest[:4], segmentMagic):
			if len(rest) < entryHeaderLen {
				tail := &segmentTail{off: off}
				if len(rest) >= 12 {
					tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(rest[4:12]))
				}
				return batches, holes, tail, nil
			}
			seq := binary.LittleEndian.Uint64(rest[4:12])
			count := binary.LittleEndian.Uint32(rest[12:16])
			pos := off + entryHeaderLen
			records, npos, ok := parseRecords(data, pos, count)
			if !ok {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			pos = npos
			if len(data)-pos < 4 {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			batches = append(batches, parsedBatch{seq: seq, records: records, off: off + 4, length: pos - off - 4})
			off = pos + 4
		case bytes.Equal(rest[:4], groupMagic):
			tail := &segmentTail{off: off}
			if len(rest) < 8 {
				return batches, holes, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var members []parsedBatch
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 12 {
					if len(data)-pos >= 8 {
						tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
					}
					return batches, holes, tail, nil
				}
				mOff := pos
				seq := binary.LittleEndian.Uint64(data[pos : pos+8])
				nrec := binary.LittleEndian.Uint32(data[pos+8 : pos+12])
				tail.seqs = append(tail.seqs, seq)
				records, npos, ok := parseRecords(data, pos+12, nrec)
				if !ok {
					return batches, holes, tail, nil
				}
				pos = npos
				members = append(members, parsedBatch{seq: seq, records: records, off: mOff, length: pos - mOff})
			}
			if len(data)-pos < 4 {
				return batches, holes, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			batches = append(batches, members...)
			off = pos + 4
		case bytes.Equal(rest[:4], holeMagic):
			tail := &segmentTail{off: off}
			if len(rest) < 8 {
				return batches, holes, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var seqs []uint64
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 8 {
					tail.seqs = append(tail.seqs, seqs...)
					return batches, holes, tail, nil
				}
				seqs = append(seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
				pos += 8
			}
			if len(data)-pos < 4 {
				tail.seqs = append(tail.seqs, seqs...)
				return batches, holes, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			holes = append(holes, seqs...)
			off = pos + 4
		default:
			return nil, nil, nil, ErrCorruptSegment
		}
	}
	return batches, holes, nil, nil
}

type parsedBatch struct {
	seq     uint64
	records [][]byte
	off     int // offset of the batch body within the segment
	length  int // length of the batch body
}

// skipRecords walks count records starting at pos using only their
// length prefixes, without copying payloads. ok is false when the data
// runs out first, which callers read as a torn write.
func skipRecords(data []byte, pos int, count uint32) (npos int, ok bool) {
	for i := uint32(0); i < count; i++ {
		if len(data)-pos < 4 {
			return 0, false
		}
		n := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
		pos += 4
		if n < 0 || len(data)-pos < n {
			return 0, false
		}
		pos += n
	}
	return pos, true
}

// parseRecords decodes count records starting at pos. ok is false when
// the data runs out first, which callers read as a torn write.
func parseRecords(data []byte, pos int, count uint32) (records [][]byte, npos int, ok bool) {
	records = make([][]byte, 0, min(int(count), 1<<20))
	for i := uint32(0); i < count; i++ {
		if len(data)-pos < 4 {
			return nil, 0, false
		}
		n := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
		pos += 4
		if n < 0 || len(data)-pos < n {
			return nil, 0, false
		}
		rec := make([]byte, n)
		copy(rec, data[pos:pos+n])
		pos += n
		records = append(records, rec)
	}
	return records, pos, true
}

