// Package log implements an append-only, batch-commit segmented log.
//
// A writer stages a batch of opaque records with Append and publishes it
// atomically with Commit, or publishes several staged batches atomically
// with CommitGroup. Readers only ever see committed batches, in strictly
// increasing sequence order starting at 1. Reads locate each batch
// through a segment-level index kept in a persistent side file, which
// Open adopts incrementally when it is intact and rebuilds from the
// segment files otherwise, so losing the index never loses data.
package log

import (
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
)

var (
	// ErrNotCommitted is returned when reading a sequence that has been
	// staged with Append but not yet committed.
	ErrNotCommitted = errors.New("log: batch not committed")
	// ErrUnknownBatch is returned for sequence 0, sequences that were
	// never reserved, sequences beyond the reserved range, and batches
	// that have already been committed.
	ErrUnknownBatch = errors.New("log: unknown batch")
	// ErrCorruptSegment is returned when a segment file fails validation
	// while opening or scanning the log.
	ErrCorruptSegment = errors.New("log: corrupt segment")
	// ErrInvalidOptions is returned by Open when the options are not
	// usable, e.g. a non-positive segment capacity.
	ErrInvalidOptions = errors.New("log: invalid options")
	// ErrSyncFailed is returned by Commit and CommitGroup when
	// Options.Sync is set and fsyncing fails. The batches stay staged
	// and keep their reserved sequences; committing them again retries.
	ErrSyncFailed = errors.New("log: sync failed")
)

var errClosed = errors.New("log: closed")

// syncFile fsyncs a file. It is a variable so tests can simulate sync
// failures; it covers both segment and index side files.
var syncFile = func(f *os.File) error { return f.Sync() }

// Options configures a Log opened with Open.
type Options struct {
	// SegmentBytes is the capacity of one segment file in bytes. Once a
	// non-empty segment would exceed it, the log rolls to a new segment.
	// A single batch or group larger than the capacity occupies its own
	// segment. Must be positive.
	SegmentBytes int
	// Sync makes Commit and CommitGroup fsync the segment and index
	// files before returning, so a returned commit is durable.
	Sync bool
}

// Batch is a group of records identified by a single sequence number.
// A Batch returned by Append is staged; after Commit or CommitGroup it
// is readable.
type Batch struct {
	seq     uint64
	records [][]byte
	owner   *Log
}

// Seq returns the sequence number reserved for the batch.
func (b Batch) Seq() uint64 { return b.seq }

// Records returns a copy of the batch's records.
func (b Batch) Records() [][]byte { return copyRecords(b.records) }

// Segment describes one segment file by the committed sequences it holds.
type Segment struct {
	FirstSeq uint64
	LastSeq  uint64
}

// entryRef locates one committed batch body inside a segment file. gen
// is the publication generation of the commit that published the batch;
// every member of a group commit shares one gen, which lets a streaming
// replay snapshot see the whole group or none of it.
type entryRef struct {
	seg    int // segment file number
	off    int // offset of the batch body within the segment
	length int // length of the batch body
	gen    uint64
}

// Log is an append-only batch-commit log stored in a directory of
// segment files plus one index side file. It is safe for concurrent
// use, but the writer side is expected to be a single goroutine (see
// README Limits).
//
// The read and write paths are decoupled: writers take mu exclusively,
// while readers hold it only for the brief index and staged-state
// lookups. Segment file reads, decoding and user callbacks happen
// outside the lock, so a slow reader or a long replay never blocks a
// committing writer.
type Log struct {
	dir  string
	opts Options

	// mu guards the mutable index and write state below. Readers never
	// hold it across file I/O, decoding or callbacks.
	mu         sync.RWMutex
	file       *os.File // current segment, nil until first write
	idxFile    *os.File // index side file, opened read-write append
	fileSize   int
	segIndex   int // index of the current segment file, 0 = none yet
	curBatches int // committed batches in the current segment
	nextSeq    uint64
	staged     map[uint64][][]byte
	index      map[uint64]entryRef
	segs       []Segment // segments holding at least one committed batch
	gen        uint64    // publication generation of the last commit
	closed     bool
}

// Open opens the log in dir, creating the directory if needed. The
// segment-level index is adopted from the persistent side file
// whenever that file is intact and consistent with the segments,
// without decoding their entries; otherwise it is rebuilt from the
// segment files. A half-written tail of the last segment — the
// remnant of a crash mid-write or between the segment and index
// syncs — is replaced by a durable hole marker without error and its
// reserved sequences stay permanent holes across reopens; any other
// inconsistency is ErrCorruptSegment.
func Open(dir string, opts Options) (*Log, error) {
	if opts.SegmentBytes <= 0 {
		return nil, ErrInvalidOptions
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var indices []int
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
			continue
		}
		n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
		if err != nil {
			continue
		}
		indices = append(indices, n)
	}
	sort.Ints(indices)

	l := &Log{
		dir:     dir,
		opts:    opts,
		nextSeq: 1,
		staged:  make(map[uint64][][]byte),
		index:   make(map[uint64]entryRef),
	}

	var frames []indexFrame
	if len(indices) > 0 {
		fs, ok := l.adoptIndex(indices)
		if !ok {
			fs, err = l.rebuildIndex(indices)
			if err != nil {
				return nil, err
			}
		}
		frames = fs
	}

	// Frames from either path describe exactly the committed set;
	// applying them builds the in-memory index, segment listing and
	// reserved-sequence bookkeeping identically.
	l.applyFrames(frames)

	if len(indices) > 0 {
		l.segIndex = indices[len(indices)-1]
		if err := l.openCurrent(); err != nil {
			return nil, err
		}
	}
	if err := l.openIndexFile(); err != nil {
		return nil, err
	}
	return l, nil
}

// adoptIndex incrementally adopts the index side file: it validates
// the side file bytes, checks every frame against the segment files
// with one streaming CRC pass per segment (entry contents are never
// decoded), and applies the crash-recovery tails. ok is false on any
// missing, truncated, stale, malformed or inconsistent side file,
// which the caller treats as "rebuild from scratch".
func (l *Log) adoptIndex(indices []int) ([]indexFrame, bool) {
	raw, err := os.ReadFile(l.indexPath())
	if err != nil || len(raw) == 0 {
		return nil, false
	}
	frames, ok := parseIndex(raw)
	if !ok {
		return nil, false
	}

	// Per-segment state while streaming the frames in order.
	type segState struct {
		endOff uint64
		crc    uint32
		opened bool
	}
	state := make(map[int]*segState)
	segOf := func(n int) *segState {
		s := state[n]
		if s == nil {
			s = &segState{}
			state[n] = s
		}
		return s
	}
	known := make(map[int]bool, len(indices))
	for _, n := range indices {
		known[n] = true
	}

	var applied []indexFrame
	lastSeg := 0
	for i := range frames {
		f := &frames[i]
		n := int(f.seg)
		if !known[n] {
			return nil, false
		}
		// Frames are appended in commit order, which is segment
		// order: no frame may move back to an earlier segment or to
		// a smaller offset within the same segment.
		if f.seg < uint64(lastSeg) || (f.seg == uint64(lastSeg) && f.endOff < segOf(n).endOff) {
			return nil, false
		}
		s := segOf(n)
		if f.endOff < s.endOff {
			return nil, false
		}
		// Verify the bytes this frame claims over [s.endOff, f.endOff).
		fh, err := os.Open(l.segmentPath(n))
		if err != nil {
			return nil, false
		}
		if _, err := fh.Seek(int64(s.endOff), io.SeekStart); err != nil {
			fh.Close()
			return nil, false
		}
		h := crc32.New(crc32.IEEETable)
		h.Write(make([]byte, s.endOff)) // seed with the prior running digest
		// crc32.Hash has no way to resume from a digest; emulate it by
		// writing a zero prefix is not equivalent, so instead update a
		// rolling digest manually while copying.
		_ = h
		fh.Close()
		var runCRC = s.crc
		fh, err = os.Open(l.segmentPath(n))
		if err != nil {
			return nil, false
		}
		if _, err := fh.Seek(int64(s.endOff), io.SeekStart); err != nil {
			fh.Close()
			return nil, false
		}
		buf := make([]byte, 32<<10)
		remaining := int64(f.endOff - s.endOff)
		for remaining > 0 {
			b := buf
			if int64(len(b)) > remaining {
				b = b[:remaining]
			}
			nr, err := fh.Read(b)
			runCRC = crc32.Update(runCRC, crc32.IEEETable, b[:nr])
			remaining -= int64(nr)
			if err == io.EOF {
				break
			}
			if err != nil {
				fh.Close()
				return nil, false
			}
		}
		fh.Close()
		if remaining != 0 || runCRC != f.segCRC {
			return nil, false
		}

		// Every data member must live inside the verified prefix and
		// must not duplicate a sequence an earlier frame published.
		if f.kind == kindData {
			if len(f.members) == 0 {
				return nil, false
			}
			for _, m := range f.members {
				if m.seq == 0 || m.off < 4 || m.length == 0 ||
					m.off+m.length > f.endOff || m.off+m.length < m.off {
					return nil, false
				}
			}
		} else if f.kind != kindHoles || (len(f.seqs) == 0 && f.kind == kindHoles) {
			return nil, false
		}
		s.endOff = f.endOff
		s.crc = f.segCRC
		lastSeg = n
		applied = append(applied, *f)
	}

	// Check each segment's actual size: the index must cover a prefix
	// of the last segment only. A prefix of any earlier segment means
	// the side file fell behind; a suffix on an earlier segment cannot
	// be a crash tail — reject and rebuild (which returns
	// ErrCorruptSegment, matching the non-tail rule).
	var tailsToRecover []struct {
		n    int
		tail *segmentTail
	}
	for i, n := range indices {
		st, err := os.Stat(l.segmentPath(n))
		if err != nil {
			return nil, false
		}
		size := uint64(st.Size())
		s := state[n]
		var covered uint64
		if s != nil {
			covered = s.endOff
		}
		if size < covered {
			return nil, false // side file ahead of the segment
		}
		if size == covered {
			continue
		}
		if i != len(indices)-1 {
			return nil, false
		}
		// Only the last segment may carry an uncommitted suffix.
		// Classify it structurally: a torn prefix becomes a tail with
		// recoverable sequences; a complete-but-unindexed entry is an
		// uncommitted remnant too, and its sequences become holes.
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, false
		}
		batches, holes, tail, err := parseSegment(data[covered:])
		if err != nil {
			return nil, false // genuine tampering: rebuild reports it
		}
		// Everything past the indexed prefix is uncommitted regardless
		// of how far the structural parse got; gather the reserved
		// sequences so they become permanent holes.
		var seqs []uint64
		for _, pb := range batches {
			seqs = append(seqs, pb.seq)
		}
		seqs = append(seqs, holes...)
		var baseCRC uint32
		var baseOff int
		if s != nil {
			baseCRC = s.crc
			baseOff = int(s.endOff)
		}
		if tail != nil {
			seqs = append(seqs, tail.seqs...)
			tailsToRecover = append(tailsToRecover, struct {
				n    int
				tail *segmentTail
			}{n: n, tail: &segmentTail{off: baseOff + tail.off, seqs: seqs, prefixCRC: baseCRC}})
		} else {
			tailsToRecover = append(tailsToRecover, struct {
				n    int
				tail *segmentTail
			}{n: n, tail: &segmentTail{off: baseOff, seqs: seqs, prefixCRC: baseCRC}})
		}
	}
	// Recovery rewrites the suffix and appends holes frames plus a
	// fresh index image; doing it before the log is usable keeps the
	// durable files consistent whether or not recovery itself crashes.
	for _, t := range tailsToRecover {
		if err := l.recoverTail(t.n, t.tail); err != nil {
			return nil, false
		}
		applied = appendHolesFrames(applied, t.n, t.tail)
	}
	return applied, true
}

// rebuildIndex fully rebuilds from the segment files: every entry is
// structurally validated (bad checksums or non-last-segment tails are
// ErrCorruptSegment), the last segment's uncommitted suffix is
// recovered as holes, and index frames are regenerated and persisted.
func (l *Log) rebuildIndex(indices []int) ([]indexFrame, error) {
	var frames []indexFrame
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		fs, tail, err := walkEntries(data, uint64(n))
		if err != nil {
			return nil, err
		}
		if tail != nil && i != len(indices)-1 {
			// A half-written tail is a crash remnant only in the
			// last segment; anywhere else it is tampering.
			return nil, ErrCorruptSegment
		}
		frames = append(frames, fs...)
		if tail != nil {
			if err := l.recoverTail(n, tail); err != nil {
				return nil, err
			}
			frames = appendHolesFrames(frames, n, tail)
		}
	}
	if err := l.persistIndexImage(frames); err != nil {
		return nil, err
	}
	return frames, nil
}

// appendHolesFrames extends frames with the holes frame(s) produced by
// recovering the tail of segment n. The recovered suffix is one hole
// marker replacing the remnant, so exactly one holes frame is added,
// positioned after the segment's prior frames.
func appendHolesFrames(frames []indexFrame, n int, tail *segmentTail) []indexFrame {
	var keep []uint64
	for _, seq := range tail.seqs {
		if seq > 0 {
			keep = append(keep, seq)
		}
	}
	if len(keep) == 0 {
		return frames
	}
	// The hole marker is appended after truncation; compute its exact
	// end offset and running CRC the same way the writer will.
	marker := encodeHoles(keep)
	endOff := uint64(tail.off) + uint64(len(marker))
	crc := crc32.Update(tail.prefixCRC, crc32.IEEETable, marker)
	hf := indexFrame{kind: kindHoles, seg: uint64(n), endOff: endOff, segCRC: crc, seqs: keep}
	// Insert preserving global frame order: frames for segment n sit
	// before frames for later segments.
	out := make([]indexFrame, 0, len(frames)+1)
	inserted := false
	for _, f := range frames {
		if !inserted && f.seg > uint64(n) {
			out = append(out, hf)
			inserted = true
		}
		out = append(out, f)
	}
	if !inserted {
		out = append(out, hf)
	}
	return out
}

// recoverTail truncates segment n at tail.off and, when the remnant
// carried recoverable sequences, appends and syncs a hole marker so
// the reserved sequences stay permanent holes across reopens.
func (l *Log) recoverTail(n int, tail *segmentTail) error {
	path := l.segmentPath(n)
	if err := os.Truncate(path, int64(tail.off)); err != nil {
		return err
	}
	var keep []uint64
	for _, seq := range tail.seqs {
		if seq > 0 {
			keep = append(keep, seq)
		}
	}
	if len(keep) == 0 {
		return nil
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
	if err != nil {
		return err
	}
	if _, err := f.Write(encodeHoles(keep)); err != nil {
		f.Close()
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// applyFrames builds the in-memory index, segment listing and
// sequence bookkeeping from adopted or rebuilt frames. Data frames
// publish batches; holes frames reserve sequences forever. The result
// is identical whichever adoption path produced the frames.
func (l *Log) applyFrames(frames []indexFrame) {
	// Track batches per segment in frame order so the segment listing
	// and current-segment counters come out exactly as before.
	segBatches := make(map[int][]frameMember)
	var segOrder []int
	for i := range frames {
		f := &frames[i]
		n := int(f.seg)
		switch f.kind {
		case kindData:
			if _, seen := segBatches[n]; !seen {
				segOrder = append(segOrder, n)
			}
			segBatches[n] = append(segBatches[n], f.members...)
			l.gen++
			for _, m := range f.members {
				l.index[m.seq] = entryRef{
					seg:    n,
					off:    int(m.off),
					length: int(m.length),
					gen:    l.gen,
				}
				if m.seq >= l.nextSeq {
					l.nextSeq = m.seq + 1
				}
			}
		case kindHoles:
			for _, seq := range f.seqs {
				if seq == 0 {
					continue
				}
				if _, ok := l.index[seq]; !ok {
					l.staged[seq] = nil
				}
				if seq >= l.nextSeq {
					l.nextSeq = seq + 1
				}
			}
		}
	}
	sort.Ints(segOrder)
	for _, n := range segOrder {
		members := segBatches[n]
		if len(members) == 0 {
			continue
		}
		seg := Segment{FirstSeq: ^uint64(0)}
		for _, m := range members {
			if m.seq < seg.FirstSeq {
				seg.FirstSeq = m.seq
			}
			if m.seq > seg.LastSeq {
				seg.LastSeq = m.seq
			}
		}
		l.segs = append(l.segs, seg)
		l.curBatches = len(members)
	}
	if len(segOrder) > 0 {
		l.segIndex = segOrder[len(segOrder)-1]
	}
}

// Append stages a batch of records and reserves the next sequence number
// for it. The batch becomes readable only after Commit or CommitGroup.
func (l *Log) Append(records [][]byte) (Batch, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return Batch{}, errClosed
	}
	recs := copyRecords(records)
	seq := l.nextSeq
	l.nextSeq++
	l.staged[seq] = recs
	return Batch{seq: seq, records: recs, owner: l}, nil
}

// Commit makes a staged batch durable and readable, and returns its
// reserved sequence number. The segment bytes are written and synced
// first, then one frame is appended and synced to the index side
// file: the batch is visible only once that frame is durable.
// Committing a batch that is not staged — including one already
// committed — returns ErrUnknownBatch. With Options.Sync a returned
// commit is durable; if either sync fails Commit returns
// ErrSyncFailed, rolls both files back, and the batch stays staged,
// keeping its reserved sequence for a retry.
func (l *Log) Commit(b Batch) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return 0, errClosed
	}
	recs, ok := l.staged[b.seq]
	if !ok || b.owner != l {
		return 0, ErrUnknownBatch
	}
	entry := encodeBatch(b.seq, recs)
	off, err := l.writeEntry(entry)
	if err != nil {
		return 0, err
	}
	bodyOff := off + len(segmentMagic)
	bodyLen := len(entry) - len(segmentMagic) - 4
	endOff := off + len(entry)
	frame := indexFrame{
		kind:   kindData,
		seg:    uint64(l.segIndex),
		endOff: uint64(endOff),
		segCRC: crc32.Update(l.segCRC(), crc32.IEEETable, entry),
		members: []frameMember{{
			seq: b.seq, off: uint64(bodyOff), length: uint64(bodyLen),
		}},
	}
	idxOff := l.indexSize()
	if err := l.publishEntry(entry, off, frame, idxOff); err != nil {
		return 0, err
	}
	delete(l.staged, b.seq)
	l.gen++
	l.index[b.seq] = entryRef{seg: l.segIndex, off: bodyOff, length: bodyLen, gen: l.gen}
	l.commitSpan(b.seq, b.seq, 1)
	return b.seq, nil
}

// CommitGroup makes several staged batches durable and readable as one
// atomic unit: a single segment write, a single segment fsync, a
// single index frame and a single index fsync, so a crash can never
// leave half of the group visible. Each batch keeps the sequence it
// reserved at Append, and the batches become visible in that reserved
// order. If any batch is not staged — including one already
// committed — nothing is written and the error is ErrUnknownBatch.
// If a sync fails, the segment bytes and index frame are rolled back,
// every batch stays staged with its reserved sequence, the error is
// ErrSyncFailed and retrying the group commits it without duplicating
// entries. Sequences reserved by a torn group stay permanent holes.
func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return nil, errClosed
	}
	if len(batches) == 0 {
		return nil, nil
	}
	members := make([]groupMember, len(batches))
	seqs := make([]uint64, len(batches))
	seen := make(map[uint64]struct{}, len(batches))
	for i, b := range batches {
		recs, ok := l.staged[b.seq]
		if !ok || b.owner != l {
			return nil, ErrUnknownBatch
		}
		if _, dup := seen[b.seq]; dup {
			return nil, ErrUnknownBatch
		}
		seen[b.seq] = struct{}{}
		members[i] = groupMember{seq: b.seq, records: recs}
		seqs[i] = b.seq
	}
	entry, offs, lens := encodeGroup(members)
	base, err := l.writeEntry(entry)
	if err != nil {
		return nil, err
	}
	fmembers := make([]frameMember, len(members))
	first, last := seqs[0], seqs[0]
	for i, m := range members {
		fmembers[i] = frameMember{
			seq:    m.seq,
			off:    uint64(base + offs[i]),
			length: uint64(lens[i]),
		}
		if m.seq < first {
			first = m.seq
		}
		if m.seq > last {
			last = m.seq
		}
	}
	frame := indexFrame{
		kind:    kindData,
		seg:     uint64(l.segIndex),
		endOff:  uint64(base + len(entry)),
		segCRC:  crc32.Update(l.segCRC(), crc32.IEEETable, entry),
		members: fmembers,
	}
	idxOff := l.indexSize()
	if err := l.publishEntry(entry, base, frame, idxOff); err != nil {
		return nil, err
	}
	l.gen++
	for i, m := range members {
		delete(l.staged, m.seq)
		l.index[m.seq] = entryRef{
			seg:    l.segIndex,
			off:    base + offs[i],
			length: lens[i],
			gen:    l.gen,
		}
	}
	l.commitSpan(first, last, len(members))
	return seqs, nil
}

// publishEntry performs the durable publication of an entry already
// written at segOff: optionally sync the segment, then append and
// optionally sync the index frame. On any sync failure both files are
// truncated back to their prior sizes and ErrSyncFailed is returned;
// the caller's batches stay staged. The caller holds l.mu.
func (l *Log) publishEntry(entry []byte, segOff int, frame indexFrame, idxOff int) error {
	if l.opts.Sync {
		if err := syncFile(l.file); err != nil {
			l.rollbackSegment(segOff)
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	frameBytes := encodeFrame(&frame)
	if _, err := l.idxFile.Write(frameBytes); err != nil {
		if l.opts.Sync {
			// The segment entry is synced but the index never
			// advertised it: roll the segment back too so a later
			// successful retry is the unique publication. Truncate
			// leaves a size the next open treats as an uncommitted
			// remnant if this process dies before re-syncing.
			l.rollbackSegment(segOff)
			l.rollbackIndex(idxOff)
			return err
		}
		l.rollbackSegment(segOff)
		l.rollbackIndex(idxOff)
		return err
	}
	if l.opts.Sync {
		if err := syncFile(l.idxFile); err != nil {
			l.rollbackIndex(idxOff)
			l.rollbackSegment(segOff)
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	return nil
}

// rollbackSegment truncates the current segment back to off.
func (l *Log) rollbackSegment(off int) {
	l.file.Truncate(int64(off))
	l.fileSize = off
	// A rollback at the start of a segment leaves it empty; segment
	// bookkeeping for a fresh segment roll is undone as well.
	if off == 0 {
		if n := len(l.segs); n > 0 && l.segs[n-1].FirstSeq == 0 {
			l.segs = l.segs[:n-1]
		}
		l.curBatches = 0
	}
}

// rollbackIndex truncates the side file back to off.
func (l *Log) rollbackIndex(off int) {
	l.idxFile.Truncate(int64(off))
}

// Read returns the records of the committed batch with the given
// sequence, located directly through the segment-level index. A staged
// but uncommitted sequence yields ErrNotCommitted; sequence 0,
// never-reserved sequences, and sequences beyond the reserved range
// yield ErrUnknownBatch.
//
// The lock is held only for the index lookup; the segment file is read
// and the body decoded without it, so a slow read never blocks writers.
func (l *Log) Read(seq uint64) ([][]byte, error) {
	l.mu.RLock()
	if l.closed {
		l.mu.RUnlock()
		return nil, errClosed
	}
	ref, ok := l.index[seq]
	if !ok {
		_, staged := l.staged[seq]
		l.mu.RUnlock()
		if staged {
			return nil, ErrNotCommitted
		}
		return nil, ErrUnknownBatch
	}
	l.mu.RUnlock()
	return l.readRef(seq, ref)
}

// scanSnapshot is a read-consistent visibility boundary: a batch is
// visible only when its publication generation is <= gen and its
// sequence is <= highSeq. The boundary is captured in one brief
// read-lock acquisition, so a group that commits after a replay starts
// (even one filling an earlier reserved hole) is either wholly inside
// the snapshot or wholly outside it.
type scanSnapshot struct {
	gen     uint64
	highSeq uint64
}

// Scan replays committed batches with sequence >= from in increasing
// sequence order, stopping at the first error returned by fn.
//
// The replay is a consistent snapshot: batches committed after the
// replay starts are invisible to it, and a group commit is seen either
// whole or not at all. The replay streams batches straight from the
// segment files one sequence at a time and keeps only the current
// batch in memory; it never loads the whole replay first. Each
// sequence lookup takes the lock briefly, while the file read, decode
// and the fn callback all run outside it, so a long replay never
// blocks writers.
func (l *Log) Scan(from uint64, fn func(Batch) error) error {
	l.mu.RLock()
	if l.closed {
		l.mu.RUnlock()
		return errClosed
	}
	snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
	l.mu.RUnlock()

	if from > snap.highSeq {
		return nil
	}
	for seq := from; ; {
		// One brief read-lock per sequence: only the index metadata is
		// touched while holding it.
		l.mu.RLock()
		ref, ok := l.index[seq]
		l.mu.RUnlock()
		// Skip holes (reserved but uncommitted sequences) and batches
		// published after the snapshot was taken.
		if ok && ref.gen <= snap.gen {
			records, err := l.readRef(seq, ref)
			if err != nil {
				return err
			}
			if err := fn(Batch{seq: seq, records: records, owner: l}); err != nil {
				return err
			}
		}
		if seq == snap.highSeq {
			break
		}
		seq++
	}
	return nil
}

// Segments lists the segments that hold committed batches, in file
// order, each with its first and last committed sequence.
func (l *Log) Segments() []Segment {
	l.mu.RLock()
	defer l.mu.RUnlock()
	out := make([]Segment, len(l.segs))
	copy(out, l.segs)
	return out
}

// Close closes the segment and index files. The log must not be used
// afterwards.
func (l *Log) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return nil
	}
	l.closed = true
	var err error
	if l.file != nil {
		err = l.file.Close()
	}
	if l.idxFile != nil {
		if cerr := l.idxFile.Close(); cerr != nil && err == nil {
			err = cerr
		}
	}
	return err
}

// readRef loads the records of a committed batch straight from its
// segment file. It performs no locking and must be called without l.mu
// held: the segment read and body decode happen entirely on the read
// path, outside the writer lock. The on-disk bytes are immutable once
// the index frame is synced (only the unindexed suffix of the very
// last segment is ever rewritten, and it never has an index entry), so
// a ref captured under the read lock stays valid afterwards. The
// returned records are freshly decoded, so callers can mutate them
// without affecting the log or later reads.
func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, error) {
	f, err := os.Open(l.segmentPath(ref.seg))
	if err != nil {
		return nil, err
	}
	defer f.Close()
	body := make([]byte, ref.length)
	if _, err := f.ReadAt(body, int64(ref.off)); err != nil && err != io.EOF {
		return nil, err
	}
	got, records, err := decodeBody(body)
	if err != nil {
		return nil, err
	}
	if got != seq {
		return nil, ErrCorruptSegment
	}
	return records, nil
}

// commitSpan records n newly committed batches covering sequences
// [first, last] in the segment listing.
func (l *Log) commitSpan(first, last uint64, n int) {
	if l.curBatches == 0 {
		l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
	} else {
		seg := &l.segs[len(l.segs)-1]
		if first < seg.FirstSeq {
			seg.FirstSeq = first
		}
		if last > seg.LastSeq {
			seg.LastSeq = last
		}
	}
	l.curBatches += n
}

// writeEntry appends one encoded entry to the current segment, rolling
// to a new segment when the current one is non-empty and would exceed
// the configured capacity, and returns the offset the entry was
// written at.
func (l *Log) writeEntry(entry []byte) (int, error) {
	if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
		if err := l.file.Close(); err != nil {
			return 0, err
		}
		l.file = nil
		l.segIndex++
		l.curBatches = 0
	}
	if l.file == nil {
		if l.segIndex == 0 {
			l.segIndex = 1
		}
		if err := l.openCurrent(); err != nil {
			return 0, err
		}
	}
	off := l.fileSize
	n, err := l.file.Write(entry)
	if err != nil {
		return 0, err
	}
	l.fileSize += n
	return off, nil
}

func (l *Log) openCurrent() error {
	f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.file = f
	l.fileSize = int(st.Size())
	return nil
}

// openIndexFile opens (creating when the log is still empty) the
// append side file and positions it at its end.
func (l *Log) openIndexFile() error {
	path := l.indexPath()
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	if st.Size() == 0 {
		if _, err := f.Write(encodeIndexShard(nil)); err != nil {
			f.Close()
			return err
		}
	}
	if _, err := f.Seek(0, io.SeekEnd); err != nil {
		f.Close()
		return err
	}
	l.idxFile = f
	return nil
}

// persistIndexImage atomically replaces the side file with the header
// followed by the rebuilt frames and syncs it, used after a full
// rebuild or crash recovery.
func (l *Log) persistIndexImage(frames []indexFrame) error {
	path := l.indexPath()
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, encodeIndexShard(frames), 0o644); err != nil {
		return err
	}
	f, err := os.OpenFile(tmp, os.O_RDONLY, 0)
	if err != nil {
		return err
	}
	if err := syncFile(f); err != nil {
		f.Close()
		return err
	}
	f.Close()
	if err := os.Rename(tmp, path); err != nil {
		return err
	}
	dir, err := os.Open(l.dir)
	if err != nil {
		return err
	}
	err = dir.Sync()
	dir.Close()
	return err
}

// segCRC returns the running CRC32 recorded by the last index frame
// for the current segment, i.e. the checksum of its committed prefix.
func (l *Log) segCRC() uint32 {
	// Maintained implicitly via frames at commit time; the in-memory
	// running digest is kept in segRunCRC.
	return l.segRunCRC
}

func (l *Log) indexSize() int {
	st, err := l.idxFile.Stat()
	if err != nil {
		return 0
	}
	return int(st.Size())
}

func (l *Log) segmentPath(index int) string {
	return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
}

func (l *Log) indexPath() string {
	return filepath.Join(l.dir, "index.idx")
}

func copyRecords(records [][]byte) [][]byte {
	out := make([][]byte, len(records))
	for i, r := range records {
		cp := make([]byte, len(r))
		copy(cp, r)
		out[i] = cp
	}
	return out
}

