// applyFrames builds the in-memory index, segment listing and
// sequence bookkeeping from adopted or rebuilt frames. Data frames
// publish batches; holes frames reserve sequences forever. The result
// is identical whichever adoption path produced the frames.
func (l *Log) applyFrames(frames []indexFrame) {
	segBatches := make(map[int][]frameMember)
	var segOrder []int
	for i := range frames {
		f := &frames[i]
		n := int(f.seg)
		switch f.kind {
		case kindData:
			if _, seen := segBatches[n]; !seen {
				segOrder = append(segOrder, n)
			}
			l.gen++
			for _, m := range f.members {
				segBatches[n] = append(segBatches[n], m)
				l.index[m.seq] = entryRef{
					seg:    n,
					off:    int(m.off),
					length: int(m.length),
					gen:    l.gen,
				}
				if m.seq >= l.nextSeq {
					l.nextSeq = m.seq + 1
				}
			}
		case kindHoles:
			for _, seq := range f.seqs {
				if seq == 0 {
					continue
				}
				if _, ok := l.index[seq]; !ok {
					l.staged[seq] = nil
				}
				if seq >= l.nextSeq {
					l.nextSeq = seq + 1
				}
			}
		}
		// The CRC and offset of the most recent frame for a segment
		// describe that segment's durable prefix; the last segment is
		// the one later commits append to.
		if n == l.segIndex || len(segOrder) > 0 && n == segOrder[len(segOrder)-1] {
			l.curSegCRC = f.segCRC
		}
	}
	sort.Ints(segOrder)
	if len(segOrder) > 0 {
		l.segIndex = segOrder[len(segOrder)-1]
	}
	for _, n := range segOrder {
		members := segBatches[n]
		if len(members) == 0 {
			continue
		}
		seg := Segment{FirstSeq: ^uint64(0)}
		for _, m := range members {
			if m.seq < seg.FirstSeq {
				seg.FirstSeq = m.seq
			}
			if m.seq > seg.LastSeq {
				seg.LastSeq = m.seq
			}
		}
		l.segs = append(l.segs, seg)
		if n == l.segIndex {
			l.curBatches = len(members)
		}
	}
	// curSegCRC must describe the current segment, including a suffix
	// that only carries a hole marker.
	if len(frames) > 0 {
		last := &frames[len(frames)-1]
		if int(last.seg) == l.segIndex {
			l.curSegCRC = last.segCRC
		}
	}
}

