				payPos += 24
			}
		} else {
			f.seqs = make([]uint64, 0, count)
			for i := uint32(0); i < count; i++ {
				f.seqs = append(f.seqs, binary.LittleEndian.Uint64(data[payPos:payPos+8]))
				payPos += 8
			}
		}
		frames = append(frames, f)
		pos = crcAt + 4
	}
	return frames, pos, true
}

