// rebuildIndex fully rebuilds the index from the segment files. Even
// on this path the salvaged side file still supplies the commit
// watermark: a frame that was synced before the crash proves its
// entry committed, while everything past the watermark in the last
// segment is an uncommitted crash suffix — structurally complete or
// not — and its reserved sequences become permanent holes. Every
// entry below the watermark is checksum-validated; bad checksums, or
// a suffix in any segment other than the last, are ErrCorruptSegment.
// The rebuilt frames are persisted as a fresh side file image.
func (l *Log) rebuildIndex(indices []int) ([]indexFrame, error) {
	// The salvageable frame prefix is evidence about committed bytes,
	// never trusted blindly: every frame it contains is verified
	// against the segments below just like incremental adoption.
	var watermark []indexFrame
	if raw, err := os.ReadFile(l.indexPath()); err == nil && len(raw) > 0 {
		if salvaged, _, headerOK := salvageIndex(raw); headerOK {
			watermark = salvaged
		}
	}
	cov := watermarkCoverage(watermark, indices)

	var frames []indexFrame
	recovered := false
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		covered := cov[n]
		if uint64(len(data)) < covered {
			// The salvaged side file claims bytes the segment does not
			// have; drop the watermark and parse the whole segment.
			covered = 0
			watermark = nil
		}
		fs, tail, err := walkEntries(data[:covered], uint64(n))
		if err != nil {
			return nil, err
		}
		if tail != nil {
			// A frame-verified prefix cannot end in a torn entry; the
			// watermark contradicts the segment.
			return nil, ErrCorruptSegment
		}
		frames = append(frames, fs...)
		if uint64(len(data)) == covered {
			continue
		}
		if i != len(indices)-1 {
			// An uncommitted suffix is a crash remnant only in the
			// last segment; anywhere else it is tampering.
			return nil, ErrCorruptSegment
		}
		hf, err := l.recoverUncommittedSuffix(n, covered, segPrefixCRC(watermark, n))
		if err != nil {
			return nil, err
		}
		if hf != nil {
			frames = append(frames, *hf)
		}
		recovered = true
	}
	// Prefer the salvaged, segment-verified frames themselves: they
	// carry the exact frame bytes the live log appended. If the
	// watermark was unusable or contradicted the segments, fall back
	// to the frames regenerated from the segment bytes.
	if watermark != nil && framesAgree(watermark, frames) {
		frames = mergeWatermarkFrames(watermark, frames)
	}
	if err := l.persistIndexImage(frames); err != nil {
		return nil, err
	}
	_ = recovered
	return frames, nil
}

// watermarkCoverage maps each segment number to the byte offset its
// latest salvaged frame covers. Frames for unknown segments or
// non-monotonic offsets are ignored by the caller via a zero map.
func watermarkCoverage(watermark []indexFrame, indices []int) map[int]uint64 {
	known := make(map[int]bool, len(indices))
	for _, n := range indices {
		known[n] = true
	}
	cov := make(map[int]uint64)
	lastSeg := 0
	for i := range watermark {
		f := &watermark[i]
		n := int(f.seg)
		if !known[n] || n < lastSeg || f.endOff < cov[n] {
			return map[int]uint64{}
		}
		cov[n] = f.endOff
		lastSeg = n
	}
	return cov
}

// segPrefixCRC returns the running CRC the watermark recorded for
// segment n's covered prefix.
func segPrefixCRC(watermark []indexFrame, n int) uint32 {
	var crc uint32
	for i := range watermark {
		if int(watermark[i].seg) == n {
			crc = watermark[i].segCRC
		}
	}
	return crc
}

// framesAgree reports whether regenerated segment frames cover exactly
// the same publications (sequence, segment, offset, length) as the
// salvaged watermark frames, in the same order, ignoring hole frames
// the rebuild may render differently.
func framesAgree(watermark, rebuilt []indexFrame) bool {
	var w, r []frameKey
	for i := range watermark {
		if watermark[i].kind == kindData {
			for _, m := range watermark[i].members {
				w = append(w, frameKey{watermark[i].seg, m})
			}
		}
	}
	for i := range rebuilt {
		if rebuilt[i].kind == kindData {
			for _, m := range rebuilt[i].members {
				r = append(r, frameKey{rebuilt[i].seg, m})
			}
		}
	}
	if len(w) != len(r) {
		return false
	}
	for i := range w {
		if w[i] != r[i] {
			return false
		}
	}
	return true
}

type frameKey struct {
	seg uint64
	m   frameMember
}

// mergeWatermarkFrames orders salvaged frames ahead of the extra
// frames rebuild appended (only a trailing holes frame in practice).
func mergeWatermarkFrames(watermark, rebuilt []indexFrame) []indexFrame {
	out := make([]indexFrame, 0, len(rebuilt)+1)
	out = append(out, watermark...)
	for i := range rebuilt {
		if rebuilt[i].kind == kindHoles {
			out = append(out, rebuilt[i])
		}
	}
	return out
}

// recoverUncommittedSuffix handles bytes of the last segment past the
// commit watermark covered, whose CRC over [0, covered) is baseCRC.
// Those bytes never formed a visible commit, however complete they
// look. Accepted shapes:
//
//   - one or more complete data entries, optionally followed by one
//     torn partial entry: all are truncated and every reserved
//     sequence becomes one permanent hole marker;
//   - exactly one complete hole marker left by a previous recovery
//     whose index image never synced: it is kept and adopted;
//   - nothing: a no-op.
//
// Anything else is ErrCorruptSegment. It returns the holes frame to
// append to the in-memory index when recovery reserved sequences.
func (l *Log) recoverUncommittedSuffix(n int, covered, baseCRC uint64) (*indexFrame, error) {
	data, err := os.ReadFile(l.segmentPath(n))
	if err != nil {
		return nil, err
	}
	if uint64(len(data)) < covered {
		return nil, ErrCorruptSegment
	}
	suf := data[covered:]
	fs, tail, err := walkEntries(suf, 0)
	if err != nil {
		return nil, ErrCorruptSegment
	}
	var dataFrames, holeFrames []indexFrame
	for i := range fs {
		switch fs[i].kind {
		case kindData:
			dataFrames = append(dataFrames, fs[i])
		case kindHoles:
			holeFrames = append(holeFrames, fs[i])
		}
	}

	// A retained marker from an earlier recovery: nothing torn, exactly
	// one hole frame and no uncommitted data entries around it.
	if tail == nil && len(dataFrames) == 0 {
		if len(holeFrames) == 0 {
			return nil, nil
		}
		if len(holeFrames) != 1 || len(fs) != 1 {
			return nil, ErrCorruptSegment
		}
		hf := holeFrames[0]
		// Re-base its relative offsets/running CRC onto the whole segment.
		end := covered + hf.endOff
		crc := crc32.Update(uint32(baseCRC), crc32.IEEETable, suf[:hf.endOff])
		return &indexFrame{
			kind: kindHoles, seg: uint64(n), endOff: end, segCRC: crc, seqs: hf.seqs,
		}, nil
	}

	// Every other accepted suffix is discarded wholesale and replaced
	// by one hole marker. A hole marker mixed with uncommitted data or
	// a torn entry is not a state this log produces: treat as corrupt.
	if len(holeFrames) > 0 {
		return nil, ErrCorruptSegment
	}
	var seqs []uint64
	for i := range dataFrames {
		for _, m := range dataFrames[i].members {
			seqs = append(seqs, m.seq)
		}
	}
	if tail != nil {
		seqs = append(seqs, tail.seqs...)
	}
	var keep []uint64
	for _, seq := range seqs {
		if seq > 0 {
			keep = append(keep, seq)
		}
	}
	t := &segmentTail{off: int(covered), seqs: keep, prefixCRC: uint32(baseCRC)}
	if err := l.recoverTail(n, t); err != nil {
		return nil, err
	}
	if len(keep) == 0 {
		return nil, nil
	}
	marker := encodeHoles(keep)
	return &indexFrame{
		kind:   kindHoles,
		seg:    uint64(n),
		endOff: covered + uint64(len(marker)),
		segCRC: crc32.Update(uint32(baseCRC), crc32.IEEETable, marker),
		seqs:   keep,
	}, nil
}

