func (l *Log) rebuildIndex(indices []int) ([]indexFrame, error) {
	// The salvageable frame prefix is evidence about the commit
	// watermark when the header is usable.
	var watermark []indexFrame
	haveWatermark := false
	if raw, err := os.ReadFile(l.indexPath()); err == nil && len(raw) > 0 {
		if salvaged, _, headerOK := salvageIndex(raw); headerOK {
			watermark = salvaged
			haveWatermark = true
		}
	}
	if haveWatermark {
		return l.rebuildWithWatermark(indices, watermark)
	}
	return l.rebuildFromScratch(indices)
}

// rebuildFromScratch is the legacy full rebuild used when there is no
// usable side file (missing or wrong version): structural completeness
// of a segment entry defines the committed set, and only the last
// segment may end in a torn partial entry.
func (l *Log) rebuildFromScratch(indices []int) ([]indexFrame, error) {
	var frames []indexFrame
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		fs, tail, err := walkEntries(data, uint64(n))
		if err != nil {
			return nil, err
		}
		if tail != nil && i != len(indices)-1 {
			// A half-written tail is a crash remnant only in the
			// last segment; anywhere else it is tampering.
			return nil, ErrCorruptSegment
		}
		frames = append(frames, fs...)
		if tail != nil {
			if err := l.recoverTail(n, tail); err != nil {
				return nil, err
			}
			frames = appendHolesFrame(frames, n, tail)
		}
	}
	if err := l.persistIndexImage(frames); err != nil {
		return nil, err
	}
	return frames, nil
}

// rebuildWithWatermark rebuilds while a valid-header side file
// supplies the commit watermark: entries its frames cover are
// checksum-verified, and everything past the watermark in the last
// segment is an uncommitted suffix (structurally complete or not)
// whose reserved sequences become permanent holes.
func (l *Log) rebuildWithWatermark(indices []int, watermark []indexFrame) ([]indexFrame, error) {
	cov := watermarkCoverage(watermark, indices)
	// A segment the watermark never mentions but earlier segments
	// reference, or an unknown segment, invalidates the watermark.
	known := make(map[int]bool, len(indices))
	for _, n := range indices {
		known[n] = true
	}
	var frames []indexFrame
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		covered, hasCover := cov[n]
		if !hasCover {
			// No frame ends in this segment. Parse the whole file as
			// durable content; any suffix it carries past a complete
			// parse is handled below only for the last segment.
			covered = uint64(len(data))
		}
		if uint64(len(data)) < covered {
			return nil, ErrCorruptSegment
		}
		fs, tail, err := walkEntries(data[:covered], uint64(n))
		if err != nil {
			return nil, err
		}
		if hasCover && tail != nil {
			// A frame-verified prefix cannot end in a torn entry; the
			// watermark contradicts the segment.
			return nil, ErrCorruptSegment
		}
		frames = append(frames, fs...)
		if uint64(len(data)) == covered {
			continue
		}
		if i != len(indices)-1 {
			// An uncommitted suffix is a crash remnant only in the
			// last segment; anywhere else it is tampering.
			return nil, ErrCorruptSegment
		}
		if !hasCover {
			// Whole-file structural parse of the last segment: it may
			// legitimately end in one torn partial entry.
			if tail != nil {
				if err := l.recoverTail(n, tail); err != nil {
					return nil, err
				}
				frames = appendHolesFrame(frames, n, tail)
			}
			continue
		}
		hf, err := l.recoverUncommittedSuffix(n, covered, segPrefixCRC(watermark, n))
		if err != nil {
			return nil, err
		}
		if hf != nil {
			frames = append(frames, *hf)
		}
	}
	// Prefer the salvaged frames themselves once the segment bytes
	// prove them: they are the exact frame records the live log
	// appended. They must be field-for-field equal to the regenerated
	// prefix; only a trailing recovery holes frame is extra.
	if framePrefixEqual(watermark, frames) {
		frames = append(append([]indexFrame{}, watermark...), frames[len(watermark):]...)
	}
	if err := l.persistIndexImage(frames); err != nil {
		return nil, err
	}
	return frames, nil
}

