// salvageIndex returns the longest strictly-valid frame prefix of a
// side file: every frame up to consumed is structurally intact and
// checksum-valid; bytes after it (a torn frame write) are ignored.
// headerOK is false when even the 8-byte header is missing or carries
// an unknown version, in which case no commit watermark survives.
func salvageIndex(data []byte) (frames []indexFrame, consumed int, headerOK bool) {
	if len(data) < 8 || string(data[:4]) != string(indexMagic) {
		return nil, 0, false
	}
	if binary.LittleEndian.Uint32(data[4:8]) != indexVersion {
		return nil, 0, false
	}
	const frameHead = 4 + 1 + 8 + 8 + 4 + 4
	pos := 8
	for pos < len(data) {
		if len(data)-pos < frameHead+4 {
			return frames, pos, true
		}
