// rebuildIndex fully rebuilds the index from the segment files. Even
// on this path the salvaged side file still supplies the commit
// watermark: a frame that was synced before the crash proves its
// entry committed, while everything past the watermark in the last
// segment is an uncommitted crash suffix — structurally complete or
// not — and its reserved sequences become permanent holes. Every
// entry below the watermark is checksum-validated; bad checksums, or
// a suffix in any segment other than the last, are ErrCorruptSegment.
// The rebuilt frames are persisted as a fresh side file image.
func (l *Log) rebuildIndex(indices []int) ([]indexFrame, error) {
	// The salvageable frame prefix is evidence about committed bytes,
	// never trusted blindly: every frame it contains is verified
	// against the segments below just like incremental adoption.
	var watermark []indexFrame
	if raw, err := os.ReadFile(l.indexPath()); err == nil && len(raw) > 0 {
		if salvaged, _, headerOK := salvageIndex(raw); headerOK {
			watermark = salvaged
		}
	}
	cov := watermarkCoverage(watermark, indices)

	var frames []indexFrame
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		covered := cov[n]
		if covered == 0 {
			// No salvaged frame ends in this segment: parse the whole
			// segment. Every segment file holds at least one entry.
			covered = uint64(len(data))
		}
		if uint64(len(data)) < covered {
			// The salvaged side file claims bytes the segment does not
			// have; discard the watermark and parse every segment whole.
			covered = 0
			watermark = nil
			cov = map[int]uint64{}
		}
		fs, tail, err := walkEntries(data[:covered], uint64(n))
		if err != nil {
			return nil, err
		}
		if tail != nil {
			// A frame-verified prefix cannot end in a torn entry; the
			// watermark contradicts the segment.
			return nil, ErrCorruptSegment
		}
		frames = append(frames, fs...)
		if uint64(len(data)) == covered {
			continue
		}
		if i != len(indices)-1 {
			// An uncommitted suffix is a crash remnant only in the
			// last segment; anywhere else it is tampering.
			return nil, ErrCorruptSegment
		}
		hf, err := l.recoverUncommittedSuffix(n, covered, segPrefixCRC(watermark, n))
		if err != nil {
			return nil, err
		}
		if hf != nil {
			frames = append(frames, *hf)
		}
	}
	// Prefer the salvaged, segment-verified frames themselves: they
	// are the exact frame bytes the live log appended. They must equal
	// the frames independently regenerated from the segment bytes;
	// only the trailing holes frame from this recovery is extra.
	if watermark != nil && framePrefixEqual(watermark, frames) {
		frames = append(append([]indexFrame{}, watermark...), frames[len(watermark):]...)
	}
	if err := l.persistIndexImage(frames); err != nil {
		return nil, err
	}
	return frames, nil
}

