		t.Fatalf("Segments = %+v, want only seq 1", got)
	}
	var seen []uint64
	l.Scan(1, func(b Batch) error { seen = append(seen, b.Seq()); return nil })
	if !reflect.DeepEqual(seen, []uint64{1}) {
		t.Fatalf("scan = %v, want [1]", seen)
