package log

import (
	"errors"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

func TestStressReopenRebuildEquivalence(t *testing.T) {
	rng := rand.New(rand.NewSource(42))
	dir := t.TempDir()
	model := map[uint64]string{} // committed seq -> payload; holes absent
	holes := map[uint64]bool{}
	next := uint64(1)

	l, err := Open(dir, Options{SegmentBytes: 64, Sync: true})
	if err != nil { t.Fatal(err) }

	segsnap := func() []Segment {
		var s []Segment
		l.mu.Lock(); s = append(s, l.segs...); l.mu.Unlock()
		return s
	}
	_ = segsnap

	for cycle := 0; cycle < 60; cycle++ {
		// 0-4 writes
		k := rng.Intn(4)
		for w := 0; w < k; w++ {
			p := fmt.Sprintf("payload-%d", next)
			b, err := l.Append([][]byte{[]byte(p)})
			if err != nil { t.Fatal(err) }
			if rng.Intn(5) == 0 {
				// group of one occasionally
				if _, err := l.CommitGroup([]Batch{b}); err != nil { t.Fatal(err) }
			} else if _, err := l.Commit(b); err != nil { t.Fatal(err) }
			model[next] = p
			next++
		}
		l.Close()

		// Mess with files before reopen.
		switch rng.Intn(7) {
		case 0:
			os.Remove(filepath.Join(dir, "index.idx"))
